import hu.laci.cms.backend.model.content.*; import java.util.*;
/** Request fields shared by content-item create and update operations. */ public class ContentItemRequest { private ContentType type; private String title; private String slug; private String summary; private String content; private String groupCode; private ContentStatus status; private Long featuredMediaId; private String publishedAt; private List<Long> tagIds; public ContentType getType(){return type;} public void setType(ContentType v){type=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getSlug(){return slug;} public void setSlug(String v){slug=v;} public String getSummary(){return summary;} public void setSummary(String v){summary=v;} public String getContent(){return content;} public void setContent(String v){content=v;} public String getGroupCode(){return groupCode;} public void setGroupCode(String v){groupCode=v;} public ContentStatus getStatus(){return status;} public void setStatus(ContentStatus v){status=v;} public Long getFeaturedMediaId(){return featuredMediaId;} public void setFeaturedMediaId(Long v){featuredMediaId=v;} public String getPublishedAt(){return publishedAt;} public void setPublishedAt(String v){publishedAt=v;} public List<Long> getTagIds(){return tagIds;} public void setTagIds(List<Long> v){tagIds=v;} }
